// pos measurement model:
float ekf_R_pos[N_MEASUREMENTS_POS];   // Kalman filter measurement noise covariance matrix (diagonal)

void ekf_set_R_pos(float R_diag[N_MEASUREMENTS_POS]) {
    for (int i=0; i<N_MEASUREMENTS_POS; i++) {
        ekf_R_pos[i] = R_diag[i];
    }
}

